package com.cpf.batch.scheduler.internal; import org.springframework.dao.DuplicateKeyException; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.sql.Timestamp; import java.time.*; import java.util.*;
@Repository public class JdbcSchedulerLeaderRepository { private final JdbcTemplate jdbc;public JdbcSchedulerLeaderRepository(JdbcTemplate j){jdbc=j;} @Transactional public Optional<Lease> acquire(String key,String id,Duration d){Instant now=Instant.now(),until=now.plus(d);int n=jdbc.update("UPDATE bat_scheduler_lease SET owner_instance_id=?,fencing_token=fencing_token+1,lease_until=?,last_heartbeat_at=?,updated_at=CURRENT_TIMESTAMP(6) WHERE scheduler_key=? AND (owner_instance_id=? OR lease_until<?)",id,Timestamp.from(until),Timestamp.from(now),key,id,Timestamp.from(now));if(n==0)try{jdbc.update("INSERT INTO bat_scheduler_lease(scheduler_key,owner_instance_id,fencing_token,lease_until,last_heartbeat_at) VALUES(?,?,1,?,?)",key,id,Timestamp.from(until),Timestamp.from(now));}catch(DuplicateKeyException e){return Optional.empty();}return jdbc.query("SELECT owner_instance_id,fencing_token,lease_until FROM bat_scheduler_lease WHERE scheduler_key=?",rs->rs.next()&&id.equals(rs.getString(1))?Optional.of(new Lease(id,rs.getLong(2),rs.getTimestamp(3).toInstant())):Optional.empty(),key);} public boolean heartbeat(String key,Lease l,Duration d){return jdbc.update("UPDATE bat_scheduler_lease SET lease_until=?,last_heartbeat_at=CURRENT_TIMESTAMP(6),updated_at=CURRENT_TIMESTAMP(6) WHERE scheduler_key=? AND owner_instance_id=? AND fencing_token=? AND lease_until>=CURRENT_TIMESTAMP(6)",Timestamp.from(Instant.now().plus(d)),key,l.instanceId(),l.fencingToken())==1;} public record Lease(String instanceId,long fencingToken,Instant leaseUntil){} }
